components/faceted-search/index:
{{> components/eyeva/faceted-search/init-image-color}}
<div id="facetedSearch" class="facetedSearch" role="region" aria-label="{{lang 'search.faceted.label'}}">
    {{#any facets visible=true}}
        <div id="facetedSearch-navList"
            class="facetedSearch-navList"
        >
            <div class="accordion accordion--navList">
                {{#each facets}}
                    {{#if visible}}
                        {{#inArray ../theme_settings.facet_img_arr (lowercase facet)}}
                            {{#if (merge this isFacetImg=true)}}{{/if}}
                        {{/inArray}}
                        {{#inArray ../theme_settings.facet_color_arr (lowercase facet)}}
                            {{#if (merge this isFacetColor=true)}}{{/if}}
                        {{/inArray}}
                        {{{dynamicComponent 'components/faceted-search/facets'}}}
                    {{/if}}
                {{/each}}
            </div>

            <div class="blocker" style="display: none;"></div>
        </div>
    {{/any}}
</div>

components/eyeva/faceted-search/init-ima:
{{#if theme_settings}}
    {{assignVar 'facet_img_size_width' (toInt (first (split theme_settings.facet_img_size 'x')))}}
    {{assignVar 'facet_color_size_width' (toInt (first (split theme_settings.facet_color_size 'x')))}}

    {{assignVar '_tmp' " "}}
    {{#each (split (lowercase theme_settings.facet_img) ',')}}
        {{assignVar '_tmp' (get 'string' (multiConcat (getVar '_tmp') ',' (trim this)))}}
    {{/each}}
    {{#all (getVar '_tmp') (merge theme_settings facet_img_arr=(split (getVar '_tmp') ','))}}
    {{/all}}

    {{assignVar '_tmp' " "}}
    {{#each (split (lowercase theme_settings.facet_color) ',')}}
        {{assignVar '_tmp' (get 'string' (multiConcat (getVar '_tmp') ',' (trim this)))}}
    {{/each}}
    {{#all (getVar '_tmp') (merge theme_settings facet_color_arr=(split (getVar '_tmp') ','))}}
    {{/all}}
{{/if}}

components/faceted-search/facets/hierarc:
{{#if items}}
<div class="accordion-block">
    {{> components/faceted-search/faceted-search-navigation}}

    <div id="facetedSearch-content--{{dashcase facet}}" class="accordion-content {{#if selected}} is-open{{/if}}">
        <ul id="facetedSearch-navList--{{dashcase facet}}" class="navList" data-facet="{{facet}}" data-has-more-results="{{has_more_results}}">
            {{#each items}}
                <li class="navList-item">
                    <a
                        href="{{url}}"
                        class="navList-action navList-action--checkbox{{#if selected }} is-selected{{/if}}{{#if has_sub_categories}} has-children{{/if}}"
                        rel="nofollow"
                        data-id="{{id}}"
                        data-faceted-search-facet>
                        {{{sanitize title}}}
                        {{#if ../show_product_counts}}
                            <span>({{count}})</span>
                        {{/if}}
                    </a>
                    {{#if children}}
                        {{> components/faceted-search/facets/hierarchy-children children}}
                    {{/if}}
                </li>
            {{/each}}
        </ul>

        {{#if show_more_toggle}}
            <a href="#facetedSearch-navList--{{dashcase facet}}" role="button" class="toggleLink">
                <span class="toggleLink-text toggleLink-text--off">{{lang 'search.faceted.show-more'}}</span>
            </a>
        {{/if}}
    </div>
</div>
{{/if}}

components/faceted-search/facets/rating:
{{#if items}}
<div class="accordion-block">
    {{> components/faceted-search/faceted-search-navigation}}

    <div id="facetedSearch-content--{{dashcase facet}}" class="accordion-content facetedSearch-content--{{dashcase facet}} {{#if selected}} is-open{{/if}}">
        <ul class="eyeva__faceted-list _flex">
            {{#each items}}
                <li class="eyeva__faceted-list-item">
                    <a href="{{url}}"
                       class="eyeva__faceted-list-action{{#if selected}} is-selected{{/if}}"
                       rel="nofollow"
                       data-faceted-search-facet>
                        <span class="rating--small">
                            {{> components/products/ratings-mini rating=(concat title '+')}}
                        </span>
                        {{#if ../show_product_counts}}
                            <span class="_count">({{count}})</span>
                        {{/if}}
                    </a>
                </li>
            {{/each}}
        </ul>
    </div>
</div>
{{/if}}
